	dc.b "ITEM                A SPECTRUM 48K COMPUTER              ",$00
	dc.b $80,$02,$0B,$80,$20,$00
	dc.b "TITLE           WISHFUL THINKING OF A MERCENARY          ",$00
	dc.b "PAGE 1           I WISH I HAD A CHEESE SANDWICH          ",$00
	dc.b "PAGE 2  I WISH THAT I COULD RECEIVE ONE MILLION CREDITS  ",$00
