	dc.b "ENCLOSED   PROF HANTZENS NEW ADDRESS IS UR CITY 07-01    ",$00
	dc.b $80,$00,$D5,$80,$20,$00
	dc.b "SHIPPERSAMONG MY EFFECTS REMOVED INTO YOUR 09-02 STORAGEIS A VERY VALUABLE PIANO- PLEASE TAKE EXTRA CARE ",$00
	dc.b "LAB NOTEON YOUR REQUEST FOR FURTHER INFO ON THE NOVABOMBIT'S POWER EQUIVALENT IS EIGHT MAXSET EXPLOSIVES ",$00
